insert into public.brevo_setup(kind, lang, step, req_id) select 'tip','en',1, public.brevo_post('/smtp/templates', $j${"templateName": "Starter Kit EN 1", "subject": "Your AI Bot Starter Kit (+ a 10-minute first win)", "isActive": true, "sender": {"name": "Bolt from geopolcoins.xyz", "email": "hello@geopolcoins.xyz"}, "replyTo": "geopolcoins1@gmail.com", "htmlContent": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"></head>\n<body style=\"margin:0;background:#eef1f6;font-family:Arial,Helvetica,sans-serif;color:#111827\">\n<div style=\"display:none;max-height:0;overflow:hidden\">Start with bot number 1. Here is how.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#eef1f6;padding:24px 12px\"><tr><td align=\"center\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:14px;overflow:hidden\">\n<tr><td style=\"background:#0a1630;padding:16px 24px;color:#f3ecd9;font-weight:bold;font-size:16px\">geopolcoins.xyz</td></tr>\n<tr><td style=\"padding:26px 24px 8px;font-size:16px;line-height:1.6\"><p style=\"margin:0 0 14px\">Hi {{ contact.FIRSTNAME | default : \"there\" }},</p><p style=\"margin:0 0 14px\">Here is your free AI Bot Starter Kit:</p><p style=\"margin:22px 0\"><a href=\"https://geopolcoins.xyz/downloads/ai-bot-starter-kit.pdf\" style=\"display:inline-block;background:#e0b43a;color:#14110a;text-decoration:none;font-weight:bold;padding:13px 22px;border-radius:10px\">Download the kit (PDF)</a></p><p style=\"margin:0 0 14px\"><b>Your 10-minute first win:</b></p><ol style=\"margin:0 0 14px;padding-left:22px\"><li style=\"margin:4px 0\">Open page 2 and fill in the Business Card (hours, prices, address).</li><li style=\"margin:4px 0\">Copy the FAQ Answer Bot prompt and paste your card into it.</li><li style=\"margin:4px 0\">Paste everything into