insert into public.brevo_setup(kind, lang, step, req_id) select 'tip','en',2, public.brevo_post('/smtp/templates', $j${"templateName": "Starter Kit EN 2", "subject": "The one thing that makes a bot actually useful", "isActive": true, "sender": {"name": "Bolt from geopolcoins.xyz", "email": "hello@geopolcoins.xyz"}, "replyTo": "geopolcoins1@gmail.com", "htmlContent": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"></head>\n<body style=\"margin:0;background:#eef1f6;font-family:Arial,Helvetica,sans-serif;color:#111827\">\n<div style=\"display:none;max-height:0;overflow:hidden\">It is not the AI. It is your facts.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#eef1f6;padding:24px 12px\"><tr><td align=\"center\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:14px;overflow:hidden\">\n<tr><td style=\"background:#0a1630;padding:16px 24px;color:#f3ecd9;font-weight:bold;font-size:16px\">geopolcoins.xyz</td></tr>\n<tr><td style=\"padding:26px 24px 8px;font-size:16px;line-height:1.6\"><p style=\"margin:0 0 14px\">Hi {{ contact.FIRSTNAME | default : \"there\" }},</p><p style=\"margin:0 0 14px\">Most bots fail for one reason: they do not know your business, so they guess. Guessing is how a bot promises a discount you never offered.</p><p style=\"margin:0 0 14px\">The fix is boring and it works: a good Business Card. Five minutes, once.</p><p style=\"margin:0 0 14px\">This page builds it for you and gives you tricky test questions for your trade:</p><p style=\"margin:22px 0\"><a href=\"https://geopolcoins.xyz/start.html\" style=\"display:inline-block;background:#e0b43a;color:#14110a;text-decoration:none;font-weight:bold;padding:13px 22px;border-radius:10px\">Build my Business Card</a></p><p style=\"margin:0 0 14px\">Fill it in, copy the card, and paste it above any bot from the kit.</p><p style=\"margin:0 0 14px\">Bolt</p></td></tr>\n<tr><td style=\"padding:16px 24px 24px;font-size:12px;line-height:1.5;color:#6b7280;border-top:1px solid #e5e7eb\">You get this email because you asked for the free AI Bot Starter Kit on geopolcoins.xyz.<br>geopolcoins.xyz · geopolcoins1@gmail.com · <a href=\"{{ unsubscribe }}\" style=\"color:#6b7280\">Unsubscribe</a></td></tr>\n</table></td></tr></table></body></html>"}$j$::jsonb) where not exists (select 1 from public.brevo_setup where kind='tip' and lang='en' and step=2 and template_id is not null) on conflict (kind, lang, step) do update set req_id = excluded.req_id;
insert into public.brevo_setup(kind, lang, step, req_id) select 'tip','en',3, public.brevo_post('/smtp/templates', $j${"templateName": "Starter Kit EN 3", "subject": "3 things your bot must never do", "isActive": true, "sender": {"name": "Bolt from geopolcoins.xyz", "email": "hello@geopolcoins.xyz"}, "replyTo": "geopolcoins1@gmail.com", "htmlContent": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"></head>\n<body style=\"margin:0;background:#eef1f6;font-family:Arial,Helvetica,sans-serif;color:#111827\">\n<div style=\"display:none;max-height:0;overflow:hidden\">Protect your customers (and yourself).</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#eef1f6;padding:24px 12px\"><tr><td align=\"center\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:14px;overflow:hidden\">\n<tr><td style=\"background:#0a1630;padding:16px 24px;color:#f3ecd9;font-weight:bold;font-size:16px\">geopolcoins.xyz</td></tr>\n<tr><td style=\"padding:26px 24px 8px;font-size:16px;line-height:1.6\"><p style=\"margin:0 0 14px\">Hi {{ contact.FIRSTNAME | default : \"there\" }},</p><p style=\"margin:0 0 14px\">A good assistant saves you time. A careless one costs you customers. Three rules we put in every bot:</p><ol style=\"margin:0 0 14px;padding-left:22px\"><li style=\"margin:4px 0\">Never confirm a booking, price or discount on its own. The team confirms.</li><li style=\"margin:4px 0\">Never give medical, legal or financial advice. It refers to a professional.</li><li style=\"margin:4px 0\">Always offer a human when the customer asks or is upset.</li></ol><p style=\"margin:0 0 14px\">Customers should also know they are talking to an AI. That is simply honest, and in the EU it is becoming the rule.</p><p style=\"margin:22px 0\"><a href=\"https://geopolcoins.xyz/answers