insert into public.brevo_setup(kind, lang, step, req_id) select 'tip','en',4, public.brevo_post('/smtp/templates', $j${"templateName": "Starter Kit EN 4", "subject": "10 bots made for your trade", "isActive": true, "sender": {"name": "Bolt from geopolcoins.xyz", "email": "hello@geopolcoins.xyz"}, "replyTo": "geopolcoins1@gmail.com", "htmlContent": "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"></head>\n<body style=\"margin:0;background:#eef1f6;font-family:Arial,Helvetica,sans-serif;color:#111827\">\n<div style=\"display:none;max-height:0;overflow:hidden\">With test questions, ready to paste.</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#eef1f6;padding:24px 12px\"><tr><td align=\"center\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:14px;overflow:hidden\">\n<tr><td style=\"background:#0a1630;padding:16px 24px;color:#f3ecd9;font-weight:bold;font-size:16px\">geopolcoins.xyz</td></tr>\n<tr><td style=\"padding:26px 24px 8px;font-size:16px;line-height:1.6\"><p style=\"margin:0 0 14px\">Hi {{ contact.FIRSTNAME | default : \"there\" }},</p><p style=\"margin:0 0 14px\">The Starter Kit covers the basics. If you want bots made for your kind of business, with the tricky questions your customers really ask, there is a pack for that:</p>{% if contact.BUSINESS_TYPE == \"salon\" %}<p style=\"margin:22px 0\"><a href=\"https://ko-fi.com/s/5ba0d6d48c\" style=\"display:inline-block;background:#e0b43a;color:#14110a;text-decoration:none;font-weight:bold;padding:13px 22px;border-radius:10px\">See the salon pack</a></p>{% elif contact.BUSINESS_TYPE == \"realestate\" %}<p style=\"margin:22px 0\"><a href=\"https://ko-fi.com/s/6b98e0ae7e\" style=\"display:inline-block;background:#e0b43a;color:#14110a;text-decoration:none;font-weight:bold;padding:13px 22p