te de visite</a></p><p style=\"margin:0 0 14px\">Remplissez, copiez la carte, et collez-la au-dessus de chaque bot du kit.</p><p style=\"margin:0 0 14px\">Bolt</p></td></tr>\n<tr><td style=\"padding:16px 24px 24px;font-size:12px;line-height:1.5;color:#6b7280;border-top:1px solid #e5e7eb\">Vous recevez cet e-mail car vous avez demandé le Starter Kit gratuit sur geopolcoins.xyz.<br>geopolcoins.xyz · geopolcoins1@gmail.com · <a href=\"{{ unsubscribe }}\" style=\"color:#6b7280\">Se désinscrire</a></td></tr>\n</table></td></tr></table></body></html>"}$j$::jsonb) where not exists (select 1 from public.brevo_setup where kind='tip' and lang='fr' and step=2 and template_id is not null) on conflict (kind, lang, step) do update set req_id = excluded.req_id;
insert into public.brevo_setup(kind, lang, step, req_id) select 'tip','fr',3, public.brevo_post('/smtp/templates', $j${"templateName": "Starter Kit FR 3", "subject": "3 choses que votre bot ne doit jamais faire", "isActive": true, "sender": {"name": "Bolt from geopolcoins.xyz", "email": "hello@geopolcoins.xyz"}, "replyTo": "geopolcoins1@gmail.com", "htmlContent": "<!doctype html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"></head>\n<body style=\"margin:0;background:#eef1f6;font-family:Arial,Helvetica,sans-serif;color:#111827\">\n<div style=\"display:none;max-height:0;overflow:hidden\">Protégez vos clients (et vous-même).</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#eef1f6;padding:24px 12px\"><tr><td align=\"center\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;background:#ffffff;border-radius:14px;overflow:hidden\">\n<tr><td style=\"background:#0a1630;padding:16px 24px;color:#f3ecd9;font-weight:bold;font-size:16px\">geopolcoins.xyz</td></tr>\n<tr><td style=\"padding:26px 24px 8px;font-size:16px;line-height:1.6\"><p style=\"margin:0 0 14px\">Bonjour{% if contact.FIRSTNAME %} {{ contact.FIRSTNAME }}{% endif %},</p><p style=\"margin:0 0 14px\">Un bon assistant vous fait gagner du temps. Un assistant négligent vous fait perdre des clients. Trois règles dans chaque bot :</p><ol style=\"margin:0 0 14px;padding-left:22px\"><li style=\"margin:4px 0\">Ne jamais confirmer seul un rendez-vous, un prix ou une remise. L’équipe confirme.</li><li style=\"margin:4px 0\">Jamais de conseil médical, juridique ou financier. Il renvoie vers un professionnel.</li><li style=\"margin:4px 0\">Toujours proposer un humain quand le client le demande ou est mécontent.</li></ol><p style=\"margin:0 0 14px\">Vos clients doivent aussi savoir qu’ils parlent à une IA. C’est honnête, et dans l’UE cela devient la règle.</p><p style=\"margin:22px 0\"><a href=\"https://geopolcoins.xyz/answers.html\" style=\"display:inline-block;background:#e0b43a;color:#14110a;text-decoration:none;font-weight:bold;padding:13px 22px;border-radius:10px\">Lire 17 réponses honnêtes</a></p><p style=\"margin:0 0 14px\">Bolt</p></td></tr>\n<tr><td style=\"padding:16px 24px 24px;font-size:12px;line-height:1.5;color:#6b7280;border-top:1px solid #e5e7eb\">Vous recevez cet e-mail car vous avez demandé le Starter Kit gratuit sur geopolcoins.xyz.<br>geopolcoins.xyz · geopolcoins1@gmail.com · <a href=\"{{ unsubscribe }}\" style=\"color:#6b7280\">Se désinscrire</a></td></tr>\n</table></td></tr></table></body></html>"}$j$::jsonb) where not exists (select 1 from public.brevo_setup where kind='tip' and lang='fr' and step=3 and template_id is not null) on conflict (kind, lang, step) do update set req_id = excluded.req_id;
